from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_22R1 import ResetRf22R1
from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_22R2 import ResetRf22R2
from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_22R3 import ResetRf22R3
from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_22R4 import ResetRf22R4
from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_23R1 import ResetRf23R1


class ResetRfFactory(OperationFactoryPrototype):
    def __init__(self):
        super(ResetRfFactory, self).__init__()

    def get_kpi(self, init_ru_id=None, admin_ru_id=None):
        """
        Gets kpi for reset rf operation.
        :param init_ru_id: id for ru from init
        :type init_ru_id: int or str
        :param admin_ru_id: id for ru from api
        :type admin_ru_id: int or str
        :return: dictionary with timeout, requirement and operation description for reset rf
        :rtype: dict
        """

        if self.bts.stream == "SBTS22R1":
            return ResetRf22R1(self.bts, init_ru_id=init_ru_id, admin_ru_id=admin_ru_id).get_kpi()

        elif self.bts.stream == "SBTS22R2":
            return ResetRf22R2(self.bts, init_ru_id=init_ru_id, admin_ru_id=admin_ru_id).get_kpi()

        elif self.bts.stream == "SBTS22R3":
            return ResetRf22R3(self.bts, init_ru_id=init_ru_id, admin_ru_id=admin_ru_id).get_kpi()

        elif self.bts.stream == "SBTS22R4":
            return ResetRf22R4(self.bts, init_ru_id=init_ru_id, admin_ru_id=admin_ru_id).get_kpi()

        elif self.bts.stream >= "SBTS23R1":
            return ResetRf23R1(self.bts, init_ru_id=init_ru_id, admin_ru_id=admin_ru_id).get_kpi()
